#!/bin/bash
set -eu
command -v python3 >/dev/null || { echo "Current MiSTer Linux with Python 3 is required."; exit 1; }
python3 -c "import sys; assert sys.version_info >= (3, 9), 'Python 3.9 or newer is required'"
work=$(mktemp -d /tmp/misterzine-jellyfin-install.XXXXXX)
trap 'rm -rf -- "$work"' EXIT
base64 -d > "$work/service.pyz" <<'MISTERZINE_INSTALLER'

MISTERZINE_INSTALLER
python3 "$work/service.pyz" install "$@" --yes --channel beta
